import { useCallback, useEffect, useState } from 'react';
import { RefreshCw, Save } from 'lucide-react';
import Alert from '../../components/ui/Alert.jsx';
import Button from '../../components/ui/Button.jsx';
import Input from '../../components/ui/Input.jsx';
import { getSettings, updateSettings } from '../../services/users.service.js';
import { useAuth } from '../../hooks/useAuth.js';
import { PERMISSIONS } from '../../utils/permissions.js';

const toForm = (settings) => ({
  staffAdjustmentQuantityThreshold: String(settings.staffAdjustmentQuantityThreshold ?? 0),
    staffAdjustmentValueThreshold: String(settings.staffAdjustmentValueThreshold ?? 0),
      nearExpiryDays: String(settings.nearExpiryDays ?? 90)
      });

      export default function SettingsPage() {
        const { hasPermission } = useAuth();
          const canEdit = hasPermission(PERMISSIONS.SETTINGS_MANAGE);

            const [settings, setSettings] = useState(null);
              const [form, setForm] = useState(null);
                const [loading, setLoading] = useState(true);
                  const [saving, setSaving] = useState(false);
                    const [error, setError] = useState('');
                      const [notice, setNotice] = useState('');

                        const load = useCallback(async () => {
                            setLoading(true);
                                setError('');
                                    try {
                                          const result = await getSettings();
                                                setSettings(result);
                                                      setForm(toForm(result));
                                                          } catch (loadError) {
                                                                setError(loadError.message || 'Settings could not be loaded.');
                                                                    } finally {
                                                                          setLoading(false);
                                                                              }
                                                                                }, []);

                                                                                  useEffect(() => {
                                                                                      load();
                                                                                        }, [load]);

                                                                                          const updateField = (field) => (event) => {
                                                                                              setForm((current) => ({ ...current, [field]: event.target.value }));
                                                                                                  if (error) {
                                                                                                        setError('');
                                                                                                            }
                                                                                                                if (notice) {
                                                                                                                      setNotice('');
                                                                                                                          }
                                                                                                                            };

                                                                                                                              const handleSubmit = async (event) => {
                                                                                                                                  event.preventDefault();

                                                                                                                                      const payload = {
                                                                                                                                            staffAdjustmentQuantityThreshold: Number(form.staffAdjustmentQuantityThreshold),
                                                                                                                                                  staffAdjustmentValueThreshold: Number(form.staffAdjustmentValueThreshold),
                                                                                                                                                        nearExpiryDays: Math.round(Number(form.nearExpiryDays))
                                                                                                                                                            };

                                                                                                                                                                if (
                                                                                                                                                                      !Number.isFinite(payload.staffAdjustmentQuantityThreshold) ||
                                                                                                                                                                            !Number.isFinite(payload.staffAdjustmentValueThreshold) ||
                                                                                                                                                                                  !Number.isFinite(payload.nearExpiryDays)
                                                                                                                                                                                      ) {
                                                                                                                                                                                            setError('Every setting needs a number.');
                                                                                                                                                                                                  return;
                                                                                                                                                                                                      }

                                                                                                                                                                                                          if (payload.nearExpiryDays < 1 || payload.nearExpiryDays > 365) {
                                                                                                                                                                                                                setError('The near-expiry window must be between 1 and 365 days.');
                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                          }

                                                                                                                                                                                                                              setSaving(true);
                                                                                                                                                                                                                                  setError('');
                                                                                                                                                                                                                                      setNotice('');
                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                const result = await updateSettings(payload);
                                                                                                                                                                                                                                                      setSettings(result);
                                                                                                                                                                                                                                                            setForm(toForm(result));
                                                                                                                                                                                                                                                                  setNotice('Settings saved.');
                                                                                                                                                                                                                                                                      } catch (saveError) {
                                                                                                                                                                                                                                                                            setError(saveError.message || 'Settings could not be saved.');
                                                                                                                                                                                                                                                                                } finally {
                                                                                                                                                                                                                                                                                      setSaving(false);
                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                  <div className="mx-auto max-w-3xl space-y-4">
                                                                                                                                                                                                                                                                                                        <header className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                          <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-maroon-500">
                                                                                                                                                                                                                                                                                                                                      Administration
                                                                                                                                                                                                                                                                                                                                                </p>
                                                                                                                                                                                                                                                                                                                                                          <h1 className="mt-1 text-2xl font-bold tracking-tight text-primary-900">Settings</h1>
                                                                                                                                                                                                                                                                                                                                                                    <p className="mt-1 text-sm text-primary-600">
                                                                                                                                                                                                                                                                                                                                                                                How the centre handles approvals and expiry warnings.
                                                                                                                                                                                                                                                                                                                                                                                          </p>
                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                          <Button variant="outline" size="sm" onClick={load} loading={loading}>
                                                                                                                                                                                                                                                                                                                                                                                                                    <RefreshCw className="h-4 w-4" aria-hidden="true" />
                                                                                                                                                                                                                                                                                                                                                                                                                              Reload
                                                                                                                                                                                                                                                                                                                                                                                                                                      </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                            </header>

                                                                                                                                                                                                                                                                                                                                                                                                                                                  {notice ? <Alert tone="success">{notice}</Alert> : null}
                                                                                                                                                                                                                                                                                                                                                                                                                                                        {error ? <Alert tone="error">{error}</Alert> : null}

                                                                                                                                                                                                                                                                                                                                                                                                                                                              {loading && !form ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="surface space-y-3 p-5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {Array.from({ length: 3 }).map((_, index) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div key={index} className="h-10 animate-pulse rounded bg-sand-100" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) : null}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {form ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <form onSubmit={handleSubmit} className="surface space-y-4 p-4 sm:p-5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h2 className="text-sm font-bold text-primary-900">Adjustment approval</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p className="mt-0.5 text-xs text-primary-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  A staff adjustment that goes beyond either limit waits for an administrator. Set a
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                limit to 0 to send every staff adjustment for review.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="grid gap-3 sm:grid-cols-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          label="Quantity limit"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        name="quantityThreshold"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    min="0"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  step="any"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                value={form.staffAdjustmentQuantityThreshold}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onChange={updateField('staffAdjustmentQuantityThreshold')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            disabled={!canEdit}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          hint="Units, ignoring direction"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                label="Value limit (₦)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              name="valueThreshold"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          min="0"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        step="any"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      value={form.staffAdjustmentValueThreshold}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChange={updateField('staffAdjustmentValueThreshold')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  disabled={!canEdit}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                hint="Naira value of the movement"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="border-t border-sand-200 pt-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h2 className="text-sm font-bold text-primary-900">Expiry warnings</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p className="mt-0.5 text-xs text-primary-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Batches inside this window count as near expiry on the dashboard and in alerts.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="mt-3 sm:max-w-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            label="Near-expiry window (days)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            name="nearExpiryDays"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            min="1"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            max="365"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            step="1"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            value={form.nearExpiryDays}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChange={updateField('nearExpiryDays')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            disabled={!canEdit}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="rounded-lg bg-sand-50 px-3 py-2 text-xs text-primary-600">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Currency: {settings?.currencySymbol || '₦'} {settings?.currency || 'NGN'} · this is fixed
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  for the centre.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {canEdit ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="flex justify-end border-t border-sand-200 pt-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Button type="submit" loading={saving}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Save className="h-4 w-4" aria-hidden="true" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {saving ? 'Saving' : 'Save settings'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="border-t border-sand-200 pt-4 text-xs text-primary-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Only administrators can change these values.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) : null}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }